"""Dependency-free Playlist Analysis Deck page."""

PLAYLIST_HTML = r'''<!doctype html>
<html><head><meta charset="utf-8"><title>CrateIQ Playlists</title><style>
:root{--bg:#0b1020;--panel:#151d32;--line:#28334f;--muted:#9aa6bf;--text:#edf2ff;--cyan:#54d5ff;--amber:#f6c967;--coral:#ff7285;--green:#71d69b}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px system-ui}.shell{width:min(1600px,96vw);margin:auto;padding:28px 0 60px}.top,.controls,.track{display:flex;gap:14px;align-items:center}.top{justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:20px}.eyebrow{color:var(--cyan);font-size:11px;letter-spacing:.14em;text-transform:uppercase}h1{margin:4px 0;font-size:32px}.nav,a{color:var(--cyan)}button,input,select{background:#1b2740;color:var(--text);border:1px solid #3c4d72;border-radius:8px;padding:10px 12px}button{cursor:pointer;font-weight:700}.primary{background:var(--cyan);color:#06101b}.panel{background:var(--panel);border:1px solid var(--line);border-radius:14px;padding:18px;margin-top:20px}.controls{flex-wrap:wrap}.controls select{min-width:300px;flex:1}.charts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin-top:16px}.chart-card{background:#10182a;border-radius:10px;padding:12px}.chart-card h3{margin:0;font-size:13px}.chart-card p{margin:3px 0;color:var(--muted);font-size:11px}.flow{height:160px;width:100%;margin-top:8px}.cards{display:grid;gap:9px;margin-top:14px}.track{background:#10182a;border-radius:10px;padding:11px;cursor:pointer}.track:hover{outline:1px solid var(--cyan)}.position{color:var(--muted);width:26px}.track-main{flex:1;min-width:0}.track-main small{color:var(--muted)}.segment-curve{display:block;height:42px;max-width:640px;width:100%;margin-top:8px;background:#121b2f;border-radius:4px}.playlist-segment-curve{display:block;height:220px;width:100%;margin-top:12px;background:#121b2f;border-radius:6px}.segment-point{cursor:pointer}.segment-flow{margin-top:12px}.track-boundary{stroke:#42506e;stroke-width:1;stroke-dasharray:3 3}.badge{font-size:11px;padding:4px 7px;border-radius:999px;background:#28334f}.bad{background:#643143;color:#ffd8df}.warn{background:#5c512b;color:#fff0b5}.ok{background:#1f5742;color:#c8f6da}.actions{display:flex;gap:6px}.actions button{padding:6px 9px;font-size:12px}.editor{display:grid;grid-template-columns:1fr 1fr;gap:14px}.picker-results{max-height:210px;overflow:auto}.pick{display:flex;gap:8px;padding:7px;border-bottom:1px solid #28334f}.empty{color:var(--muted);padding:18px;text-align:center}@media(max-width:800px){.top,.editor{display:block}.nav{margin-top:12px}.controls select{width:100%;margin:8px 0}.charts{grid-template-columns:1fr}.track{align-items:flex-start}.badges{display:grid;gap:4px}}
</style></head><body><main class="shell"><header class="top"><div><div class="eyebrow">Playlist analysis deck</div><h1>CrateIQ Playlists</h1><div class="muted">Plan the musical flow before the next transition.</div></div><nav class="nav"><a href="/">Track analysis</a></nav></header><section class="panel"><div class="controls"><select id="playlist"></select><button id="new" class="primary">New playlist</button><button id="rename">Rename</button><button id="restore">Restore source order</button><button id="delete">Delete local copy</button></div><div id="overview"></div><div id="charts" class="charts"></div></section><section class="panel"><button id="toggle-flow">Show all segment flow</button><div id="segment-flow" class="segment-flow" hidden></div></section><section class="panel"><div class="eyebrow">Ordered tracks</div><div id="tracks" class="cards"></div></section><section class="panel"><div class="eyebrow">Add analyzed tracks</div><div class="editor"><div><input id="search" type="search" placeholder="Search title or artist"><div id="results" class="picker-results"></div></div><div><p class="muted">Selected tracks are appended to the editable local playlist.</p><div id="selected" class="picker-results"></div><button id="create" class="primary">Create playlist from selection</button></div></div></section></main><script>
let catalog=[],playlists=[],current='',detail=null,chosen=[];const $=id=>document.getElementById(id);const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));const fmt=v=>typeof v==='number'&&Number.isFinite(v)?(Math.abs(v)>=100?Math.round(v):v.toFixed(2)):'—';
async function request(url,options){let response=await fetch(url,options);return response.json()}async function boot(){[catalog,playlists]=await Promise.all([request('/api/tracks'),request('/api/playlists')]);renderPicker();current=playlists[0]?.id||'';if(current)load()}
function renderPicker(){let selected=current;$('playlist').innerHTML=playlists.map(p=>`<option value="${p.id}">${esc(p.name)} · ${p.trackCount} tracks${p.source==='rekordbox'?' · Rekordbox':''}</option>`).join('');$('playlist').value=selected}
async function refresh(selectId){playlists=await request('/api/playlists');current=selectId||current||playlists[0]?.id||'';renderPicker();if(current)load()}
async function load(){if(!current)return;detail=await request(`/api/playlist?playlist_id=${encodeURIComponent(current)}`);renderDetail()}
function points(values){return values.map((value,index)=>({x:24+index*952/Math.max(values.length-1,1),y:145-value*115}))}function smoothPath(values){let p=points(values);if(!p.length)return '';let d=`M ${p[0].x} ${p[0].y}`;for(let i=0;i<p.length-1;i++){let a=p[i],b=p[i+1],before=p[i-1]||a,after=p[i+2]||b;d+=` C ${a.x+(b.x-before.x)/6} ${a.y+(b.y-before.y)/6}, ${b.x-(after.x-a.x)/6} ${b.y-(after.y-a.y)/6}, ${b.x} ${b.y}`}return d}function chart(key,title,color,units=''){let values=detail.trends[key]||[],raw=detail.raw_trends[key]||[],dots=points(values).map((point,index)=>{let track=detail.tracks[index]||{},tip=`${track.title||`Track ${index+1}`}: ${fmt(raw[index])}${units}`;return `<circle cx="${point.x}" cy="${point.y}" r="3" fill="${color}" pointer-events="none"/><circle cx="${point.x}" cy="${point.y}" r="16" fill="transparent"><title>${esc(tip)}</title></circle>`}).join('');return `<article class="chart-card"><h3>${title}</h3><svg class="flow" viewBox="0 0 1000 160" preserveAspectRatio="none"><line x1="24" y1="145" x2="976" y2="145" stroke="#526079"/><path d="${smoothPath(values)}" fill="none" stroke="${color}" stroke-width="3"/>${dots}</svg></article>`}
function curvePath(points){if(!points.length)return '';let d=`M ${points[0].x} ${points[0].y}`;for(let i=0;i<points.length-1;i++){let a=points[i],b=points[i+1],before=points[i-1]||a,after=points[i+2]||b;d+=` C ${a.x+(b.x-before.x)/6} ${a.y+(b.y-before.y)/6}, ${b.x-(after.x-a.x)/6} ${b.y-(after.y-a.y)/6}, ${b.x} ${b.y}`}return d}
function segmentCurve(track){let segments=track.segments||[];if(!segments.length)return '<span class="muted">Segment energy unavailable</span>';let width=800,height=42,last=Math.max(segments.length-1,1),points=segments.map((s,index)=>({x:index*width/last,y:height-4-s.normalized_energy*(height-8)})),dots=segments.map((s,index)=>{let point=points[index],tip=`${track.title} · ${s.type} · ${fmt(s.start)}–${fmt(s.end)}s · energy ${fmt(s.energy)}`;return `<circle cx="${point.x}" cy="${point.y}" r="2" fill="#54d5ff" pointer-events="none"/><circle class="segment-point" data-track="${track.id}" data-segment="${s.index}" cx="${point.x}" cy="${point.y}" r="10" fill="transparent"><title>${esc(tip)}</title></circle>`}).join('');return `<svg class="segment-curve" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none"><line x1="0" y1="${height-3}" x2="${width}" y2="${height-3}" stroke="#34415d"/><path d="${curvePath(points)}" fill="none" stroke="#54d5ff" stroke-width="2"/>${dots}</svg>`}
function playlistSegmentCurve(){let tracks=detail.segment_flow.filter(track=>track.segments?.length),segments=tracks.flatMap(track=>track.segments.map(segment=>({...segment,track_id:track.track_id,title:track.title})));if(!segments.length)return '<span class="muted">Segment energy unavailable for this playlist.</span>';let width=1000,height=220,last=Math.max(segments.length-1,1),points=segments.map((segment,index)=>({x:20+index*960/last,y:height-18-(segment.playlist_normalized_energy??segment.normalized_energy)*(height-40)})),offset=0,boundaries=tracks.map((track,index)=>{let boundary=index?`<line class="track-boundary" x1="${points[offset].x}" y1="10" x2="${points[offset].x}" y2="${height-18}"><title>${esc(track.title)}</title></line>`:'';offset+=track.segments.length;return boundary}).join(''),dots=segments.map((segment,index)=>{let point=points[index],tip=`${segment.title} · ${segment.type} · ${fmt(segment.start)}–${fmt(segment.end)}s · energy ${fmt(segment.energy)}`;return `<circle cx="${point.x}" cy="${point.y}" r="2.5" fill="#54d5ff" pointer-events="none"/><circle class="segment-point" data-track="${segment.track_id}" data-segment="${segment.index}" cx="${point.x}" cy="${point.y}" r="12" fill="transparent"><title>${esc(tip)}</title></circle>`}).join('');return `<svg class="playlist-segment-curve" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none"><line x1="20" y1="${height-18}" x2="980" y2="${height-18}" stroke="#34415d"/>${boundaries}<path d="${curvePath(points)}" fill="none" stroke="#54d5ff" stroke-width="3"/>${dots}</svg>`}
function renderFlow(){let flow=$('segment-flow');flow.innerHTML=`<div class="muted">Segment energy across the complete playlist. Dashed lines mark a new track.</div>${playlistSegmentCurve()}`;flow.querySelectorAll('.segment-point').forEach(node=>node.addEventListener('click',event=>{event.stopPropagation();window.location=`/?track_id=${encodeURIComponent(node.dataset.track)}&segment_index=${node.dataset.segment}`}))}
function renderDetail(){let valid=detail.tracks.filter(t=>t.available).length;$('overview').innerHTML=`<h2>${esc(detail.name)}</h2><div class="muted">${detail.tracks.length} tracks · ${valid} analyzed · ${detail.source==='rekordbox'?'Imported from Rekordbox XML':'Editable CrateIQ playlist'}</div>`;$('charts').innerHTML=chart('energy','Playlist energy','#54d5ff')+chart('bass','Bass','#ff7285')+chart('rhythm','Rhythm density','#f6c967')+chart('brightness','Brightness','#ba8df5',' Hz')+chart('tempo','Tempo','#71d69b',' BPM');renderFlow();$('tracks').innerHTML=detail.tracks.length?detail.tracks.map((t,i)=>`<article class="track" data-id="${t.id}"><span class="position">${i+1}</span><div class="track-main"><b>${esc(t.title)}</b> <small>· ${esc(t.artist||'Unknown artist')} · ${fmt(t.bpm)} BPM · ${esc(t.camelot||t.key||'—')}</small><br><small>${t.available?'Playlist average: energy '+fmt(t.features.energy)+' · Bass '+fmt(t.features.bass)+' · Rhythm '+fmt(t.features.rhythm)+' · Brightness '+fmt(t.features.brightness):'Analysis unavailable'}</small>${segmentCurve(t)}${t.transition.reasons.length?`<br><small>${esc(t.transition.reasons.join(' · '))}</small>`:''}${t.outlier.reasons.length?`<br><small>${esc(t.outlier.reasons.join(' · '))}</small>`:''}</div><div class="badges">${badge(t.transition)}${badge(t.outlier)}</div><div class="actions"><button data-action="up" ${i?'':'disabled'}>↑</button><button data-action="down" ${i<detail.tracks.length-1?'':'disabled'}>↓</button><button data-action="remove">Remove</button></div></article>`).join(''):'<div class="empty">No tracks yet. Search the analyzed library below to create a playlist.</div>';document.querySelectorAll('.segment-point').forEach(node=>node.addEventListener('click',event=>{event.stopPropagation();window.location=`/?track_id=${encodeURIComponent(node.dataset.track)}&segment_index=${node.dataset.segment}`}));document.querySelectorAll('.track').forEach(node=>node.addEventListener('click',event=>{let action=event.target.dataset.action;if(action){event.stopPropagation();edit(action,Number([...document.querySelectorAll('.track')].indexOf(node)));return}window.location=`/?track_id=${encodeURIComponent(node.dataset.id)}`}))}
function badge(item){return item.score?`<span class="badge ${item.severity==='high'?'bad':'warn'}">${esc(item.label)}</span>`:`<span class="badge ok">${esc(item.label)}</span>`}
async function edit(action,index){let ids=detail.tracks.map(t=>t.id);if(action==='remove')ids.splice(index,1);if(action==='up')([ids[index-1],ids[index]]=[ids[index],ids[index-1]]);if(action==='down')([ids[index+1],ids[index]]=[ids[index],ids[index+1]]);let value=await request('/api/playlists',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'update',playlist_id:current,track_ids:ids})});await refresh(value.id)}
$('playlist').addEventListener('change',e=>{current=e.target.value;load()});$('toggle-flow').addEventListener('click',()=>{let flow=$('segment-flow');flow.hidden=!flow.hidden;$('toggle-flow').textContent=flow.hidden?'Show all segment flow':'Hide all segment flow'});$('new').addEventListener('click',async()=>{let name=prompt('Playlist name');if(!name)return;let value=await request('/api/playlists',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'create',name,track_ids:[]})});await refresh(value.id)});$('rename').addEventListener('click',async()=>{if(!detail)return;let name=prompt('Playlist name',detail.name);if(!name)return;let value=await request('/api/playlists',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'update',playlist_id:current,name})});await refresh(value.id)});$('restore').addEventListener('click',async()=>{let value=await request('/api/playlists',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'restore',playlist_id:current})});if(value.id)await refresh(value.id)});$('delete').addEventListener('click',async()=>{if(!confirm('Delete this local playlist?'))return;await request('/api/playlists',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'delete',playlist_id:current})});current='';await refresh()});
function renderSearch(){let q=$('search').value.toLowerCase(),items=catalog.filter(t=>`${t.title} ${t.artist}`.toLowerCase().includes(q)).slice(0,25);$('results').innerHTML=items.map(t=>`<label class="pick"><input type="checkbox" data-id="${t.id}" ${chosen.includes(t.id)?'checked':''}><span>${esc(t.title)}<br><small>${esc(t.artist)}</small></span></label>`).join('');$('results').querySelectorAll('input').forEach(box=>box.addEventListener('change',()=>{chosen=box.checked?[...chosen,box.dataset.id]:chosen.filter(id=>id!==box.dataset.id);renderChosen();renderSearch()}))}function renderChosen(){$('selected').innerHTML=chosen.map((id,i)=>{let t=catalog.find(x=>x.id===id);return `<div class="pick">${i+1}. ${esc(t?.title||id)}</div>`}).join('')}$('search').addEventListener('input',renderSearch);$('create').addEventListener('click',async()=>{if(!chosen.length)return;let name=prompt('Playlist name');if(!name)return;let value=await request('/api/playlists',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'create',name,track_ids:chosen})});chosen=[];renderChosen();await refresh(value.id)});boot();
</script></body></html>'''
